function collectActiveUsers(array $users, DateTimeImmutable $cutoff): array
{
    $active = [];

    foreach ($users as $user) {
        if (!$user->isOnline || $user->lastSeenAt <= $cutoff) {
            continue;
        }

        $active[] = $user->name;
    }

    return $active;
}

class ScoreController extends Controller
{
    public function store(Request $request): JsonResponse
    {
        $validated = $request->validate([
            'value' => ['required', 'integer', 'min:0'],
            'language' => ['required', 'string'],
        ]);

        $score = $request->user()->scores()->create($validated);

        return response()->json($score, 201);
    }
}

function groupPostsByTag(iterable $posts): array
{
    $grouped = [];

    foreach ($posts as $post) {
        foreach ($post->tags as $tag) {
            $grouped[$tag] ??= [];
            $grouped[$tag][] = $post->slug;
        }
    }

    return $grouped;
}

function buildSummary(Project $project): string
{
    if (trim($project->name) === '') {
        throw new InvalidArgumentException('missing project name');
    }

    $summary = strtolower("{$project->name}:{$project->branch}");

    return str_replace(' ', '-', $summary);
}

function topScores(array $entries, int $limit = 5): array
{
    usort($entries, fn ($left, $right) => $right->score <=> $left->score);

    return array_slice(
        array_filter($entries, fn ($entry) => $entry->score > 0),
        0,
        $limit,
    );
}

enum SubmitStatus: string
{
    case Idle = 'idle';
    case Saving = 'saving';
    case Saved = 'saved';
    case Error = 'error';

    public function isTerminal(): bool
    {
        return match ($this) {
            self::Saved, self::Error => true,
            default => false,
        };
    }
}

function loadConfig(string $path): Config
{
    if (!is_readable($path)) {
        throw new RuntimeException("cannot read config: {$path}");
    }

    $raw = file_get_contents($path);
    $decoded = json_decode($raw, true, flags: JSON_THROW_ON_ERROR);

    return Config::fromArray($decoded);
}

function clampScore(int $score, int $minimum, int $maximum): int
{
    return match (true) {
        $score < $minimum => $minimum,
        $score > $maximum => $maximum,
        default => $score,
    };
}

function indexBy(iterable $items, callable $keyFn): array
{
    $indexed = [];

    foreach ($items as $item) {
        $indexed[$keyFn($item)] = $item;
    }

    return $indexed;
}

$usersById = indexBy($users, fn ($user) => $user->id);

function chunked(iterable $items, int $size): Generator
{
    if ($size <= 0) {
        throw new InvalidArgumentException('size must be positive');
    }

    $batch = [];

    foreach ($items as $item) {
        $batch[] = $item;

        if (count($batch) === $size) {
            yield $batch;
            $batch = [];
        }
    }

    if (count($batch) > 0) {
        yield $batch;
    }
}
